/// A built-in module's text, by its name; `` for none.
pub fn built_in_text(path: Str) -> Str {
    if string_eq_p(path, str_lit("fx26:conditions.fx")) {
        built_in_0()
    } else if string_eq_p(path, str_lit("fx26:arm64-types.fx")) {
        built_in_1()
    } else if string_eq_p(path, str_lit("fx26:arm64.fx")) {
        built_in_2()
    } else if string_eq_p(path, str_lit("fx26:x86_64-types.fx")) {
        built_in_3()
    } else if string_eq_p(path, str_lit("fx26:x86_64.fx")) {
        built_in_4()
    } else if string_eq_p(path, str_lit("fx26:convention-types.fx")) {
        built_in_5()
    } else if string_eq_p(path, str_lit("fx26:convention.fx")) {
        built_in_6()
    } else if string_eq_p(path, str_lit("fx26:layout.fx")) {
        built_in_7()
    } else if string_eq_p(path, str_lit("fx26:layout-types.fx")) {
        built_in_8()
    } else if string_eq_p(path, str_lit("fx26:native-layout.fx")) {
        built_in_9()
    } else if string_eq_p(path, str_lit("fx26:standard.fx")) {
        built_in_10()
    } else {
        str_lit("")
    }
}

